function setView(name, push=true){
  const view=views[name]||views.map; workspace.innerHTML=view();
  $$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  $('.sidebar').classList.remove('open');
  if(push) history.replaceState(null,'',`#${name}`);
  window.scrollTo(0,0);
}
function toast(message='Action completed successfully'){const t=$('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function openDialog(title,body){$('#dialog-content').innerHTML=`<h2>${title}</h2><p>${body}</p><div class="dialog-fields"><label>Assigned team<select><option>North Division</option><option>South Hub</option></select></label><label>Operational note<textarea rows="3" placeholder="Add context…"></textarea></label><button class="btn primary" value="default">Confirm action</button></div>`;$('#action-dialog').showModal()}
document.addEventListener('click',e=>{
  const view=e.target.closest('[data-view]'); if(view){setView(view.dataset.view);return}
  const action=e.target.closest('[data-action]'); if(!action)return;
  const a=action.dataset.action;
  if(['quick-task','new-task','expense','leave','tenant'].includes(a)) openDialog(action.textContent.trim(),'Configure this operation, assign ownership, and add an auditable note.');
  else if(a==='toggle') action.classList.toggle('off');
  else if(['task-detail','expense-detail','tenant-detail','inspect-attendance'].includes(a)) toast('Inspector opened with live record context');
  else toast(a==='publish'?'Version published to the active policy engine':a==='approve'?'Approval recorded and audit trail updated':a==='save'?'Configuration saved and propagated':'Action queued successfully');
});
$('.mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
$('.mode').addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){$$('.mode button').forEach(b=>b.classList.toggle('active',b===e.target));toast(`${e.target.textContent} mode active`)}});
$('#punch-button').addEventListener('click',e=>{e.target.textContent=e.target.textContent==='Punch out'?'Punch in':'Punch out';toast('Punch state updated with time and location evidence')});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}});
let seconds=4*3600+18*60+22;setInterval(()=>{seconds++;const h=String(Math.floor(seconds/3600)).padStart(2,'0'),m=String(Math.floor(seconds%3600/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');$('#clock').textContent=`${h}:${m}:${s}`},1000);
setView(location.hash.slice(1)||'map',false);
